@dataclass
class CheckResult:
    status: str = "FAIL"
    email: str = ""
    password: str = ""
    msg: str = ""
    plan: str = "-"
    expire: str = "-"
    days: str = "-"
    renew: str = "-"
    pay: str = "-"
    pptp: str = "-:-"
    ovpn: str = "-:-"

    def hit_line(self) -> str:
        return (f"{self.email}:{self.password} | plan={self.plan} | "
                f"exp={self.expire} ({self.days}d) | renew={self.renew} | "
                f"pay={self.pay} | pptp={self.pptp} | ovpn={self.ovpn}")
